{"content": "1|// make.fun's reference VM for its tiny stack ISA (ISA.md beside this file): the one the generator runs every drawn
2|// program on to record its expected output and exit code. Pure: it reads nothing but its arguments.
3|//
4|//   run(program, input) => { stdout: Uint8Array, exit: number, trap: number | null, steps: number }
5|//
6|// Every rule below is ISA.md's, in the order ISA.md states it; a change here is a change to the ISA.
7|
8|/** The machine's bounds (ISA.md "The machine"). */
9|export const STACK_MAX = 256;
10|export const CALLS_MAX = 64;
11|export const MEMORY_WORDS = 256;
12|export const STEP_LIMIT = 1_000_000;
13|export const OUTPUT_MAX = 65_536;
14|
15|/** The trap codes (ISA.md "Traps"): the exit code of a program that traps. */
16|export const TRAP = Object.freeze({
17|  UNDERFLOW: 2,
18|  OVERFLOW: 3,
19|  DIV_ZERO: 4,
20|  BAD_OPCODE: 5,
21|  MEMORY: 6,
22|  CALL_DEPTH: 7,
23|  RET_EMPTY: 8,
24|  PC: 9,
25|  STEPS: 10,
26|  OUTPUT: 11,
27|});
28|
29|/** Every opcode: its byte, its name, the bytes of its immediate, what it pops and what it pushes. */
30|export const OPS = Object.freeze([
31|  [0x00, 'HALT', 0, 0, 0],
32|  [0x01, 'PUSH8', 1, 0, 1],
33|  [0x02, 'PUSH32', 4, 0, 1],
34|  [0x03, 'POP', 0, 1, 0],
35|  [0x04, 'DUP', 0, 1, 2],
36|  [0x05, 'SWAP', 0, 2, 2],
37|  [0x06, 'OVER', 0, 2, 3],
38|  [0x07, 'ROT', 0, 3, 3],
39|  [0x10, 'ADD', 0, 2, 1],
40|  [0x11, 'SUB', 0, 2, 1],
41|  [0x12, 'MUL', 0, 2, 1],
42|  [0x13, 'DIV', 0, 2, 1],
43|  [0x14, 'MOD', 0, 2, 1],
44|  [0x15, 'DIVU', 0, 2, 1],
45|  [0x16, 'MODU', 0, 2, 1],
46|  [0x17, 'NEG', 0, 1, 1],
47|  [0x18, 'AND', 0, 2, 1],
48|  [0x19, 'OR', 0, 2, 1],
49|  [0x1a, 'XOR', 0, 2, 1],
50|  [0x1b, 'NOT', 0, 1, 1],
51|  [0x1c, 'SHL', 0, 2, 1],
52|  [0x1d, 'SHR', 0, 2, 1],
53|  [0x1e, 'SHRU', 0, 2, 1],
54|  [0x20, 'EQ', 0, 2, 1],
55|  [0x21, 'LT', 0, 2, 1],
56|  [0x22, 'LTU', 0, 2, 1],
57|  [0x30, 'JMP', 2, 0, 0],
58|  [0x31, 'JZ', 2, 1, 0],
59|  [0x32, 'JNZ', 2, 1, 0],
60|  [0x33, 'CALL', 2, 0, 0],
61|  [0x34, 'RET', 0, 0, 0],
62|  [0x40, 'LOAD', 0, 1, 1],
63|  [0x41, 'STORE', 0, 2, 0],
64|  [0x50, 'PRINT', 0, 1, 0],
65|  [0x51, 'PUTC', 0, 1, 0],
66|  [0x52, 'IN', 0, 0, 1],
67|  [0x53, 'EXIT', 0, 1, 0],
68|]);
69|
70|/** Opcode byte to [byte, name, immediate bytes, pops, pushes]. */
71|export const OP_BY_BYTE = new Map(OPS.map((o) => [o[0], o]));
72|/** Opcode name to its byte. */
73|export const OP_BYTE = Object.freeze(Object.fromEntries(OPS.map((o) => [o[1], o[0]])));
74|
75|const enc = new TextEncoder();
76|
77|/** Runs `program` (bytes) on `input` (bytes) to its end: what it wrote, its exit code and its trap (null when it exited). */
78|export function run(program, input) {
79|  const n = program.length;
80|  const D = new Int32Array(STACK_MAX);
81|  let sp = 0;
82|  const C = new Int32Array(CALLS_MAX);
83|  let csp = 0;
84|  const M = new Int32Array(MEMORY_WORDS);
85|  const out = new Uint8Array(OUTPUT_MAX);
86|  let olen = 0;
87|  let inPos = 0;
88|  let pc = 0;
89|  let steps = 0;
90|  const done = (exit, trap) => ({ stdout: out.slice(0, olen), exit, trap, steps });
91|  const trap = (code) => done(code, code);
92|
93|  for (;;) {
94|    if (steps === STEP_LIMIT) return trap(TRAP.STEPS);
95|    if (pc < 0 || pc >= n) return trap(TRAP.PC);
96|    const op = OP_BY_BYTE.get(program[pc]);
97|    if (op === undefined) return trap(TRAP.BAD_OPCODE);
98|    const [, name, imm, pops, pushes] = op;
99|    if (pc + imm >= n) return trap(TRAP.PC);
100|    steps++;
101|    const next = pc + 1 + imm;
102|    if (sp < pops) return trap(TRAP.UNDERFLOW);
103|    if (sp - pops + pushes > STACK_MAX) return trap(TRAP.OVERFLOW);
104|    pc = next;
105|    switch (name) {
106|      case 'HALT':
107|        return done(0, null);
108|      case 'PUSH8':
109|        D[sp++] = (program[next - 1] << 24) >> 24;
110|        break;
111|      case 'PUSH32':
112|        D[sp++] = program[next - 4] | (program[next - 3] << 8) | (program[next - 2] << 16) | (program[next - 1] << 24);
113|        break;
114|      case 'POP':
115|        sp--;
116|        break;
117|      case 'DUP':
118|        D[sp] = D[sp - 1];
119|        sp++;
120|        break;
121|      case 'SWAP': {
122|        const t = D[sp - 1];
123|        D[sp - 1] = D[sp - 2];
124|        D[sp - 2] = t;
125|        break;
126|      }
127|      case 'OVER':
128|        D[sp] = D[sp - 2];
129|        sp++;
130|        break;
131|      case 'ROT': {
132|        const a = D[sp - 3];
133|        D[sp - 3] = D[sp - 2];
134|        D[sp - 2] = D[sp - 1];
135|        D[sp - 1] = a;
136|        break;
137|      }
138|      case 'NEG':
139|        D[sp - 1] = -D[sp - 1] | 0;
140|        break;
141|      case 'NOT':
142|        D[sp - 1] = ~D[sp - 1];
143|        break;
144|      case 'ADD':
145|      case 'SUB':
146|      case 'MUL':
147|      case 'DIV':
148|      case 'MOD':
149|      case 'DIVU':
150|      case 'MODU':
151|      case 'AND':
152|      case 'OR':
153|      case 'XOR':
154|      case 'SHL':
155|      case 'SHR':
156|      case 'SHRU':
157|      case 'EQ':
158|      case 'LT':
159|      case 'LTU': {
160|        const b = D[sp - 1];
161|        const a = D[sp - 2];
162|        let r;
163|        switch (name) {
164|          case 'ADD':
165|            r = (a + b) | 0;
166|            break;
167|          case 'SUB':
168|            r = (a - b) | 0;
169|            break;
170|          case 'MUL':
171|            r = Math.imul(a, b);
172|            break;
173|          case 'DIV':
174|            if (b === 0) return trap(TRAP.DIV_ZERO);
175|            r = a === -2147483648 && b === -1 ? a : (a / b) | 0;
176|            break;
177|          case 'MOD':
178|            if (b === 0) return trap(TRAP.DIV_ZERO);
179|            r = b === -1 ? 0 : a % b | 0;
180|            break;
181|          case 'DIVU':
182|            if (b === 0) return trap(TRAP.DIV_ZERO);
183|            r = Math.floor((a >>> 0) / (b >>> 0)) | 0;
184|            break;
185|          case 'MODU':
186|            if (b === 0) return trap(TRAP.DIV_ZERO);
187|            r = (a >>> 0) % (b >>> 0) | 0;
188|            break;
189|          case 'AND':
190|            r = a & b;
191|            break;
192|          case 'OR':
193|            r = a | b;
194|            break;
195|          case 'XOR':
196|            r = a ^ b;
197|            break;
198|          case 'SHL':
199|            r = a << (b & 31);
200|            break;
201|          case 'SHR':
202|            r = a >> (b & 31);
203|            break;
204|          case 'SHRU':
205|            r = (a >>> (b & 31)) | 0;
206|            break;
207|          case 'EQ':
208|            r = a === b ? 1 : 0;
209|            break;
210|          case 'LT':
211|            r = a < b ? 1 : 0;
212|            break;
213|          case 'LTU':
214|            r = a >>> 0 < b >>> 0 ? 1 : 0;
215|            break;
216|        }
217|        sp -= 2;
218|        D[sp++] = r;
219|        break;
220|      }
221|      case 'JMP':
222|      case 'JZ':
223|      case 'JNZ': {
224|        const rel = ((program[next - 2] | (program[next - 1] << 8)) << 16) >> 16;
225|        let take = true;
226|        if (name !== 'JMP') {
227|          const v = D[--sp];
228|          take = name === 'JZ' ? v === 0 : v !== 0;
229|        }
230|        if (take) pc = next + rel;
231|        break;
232|      }
233|      case 'CALL':
234|        if (csp === CALLS_MAX) return trap(TRAP.CALL_DEPTH);
235|        C[csp++] = next;
236|        pc = program[next - 2] | (program[next - 1] << 8);
237|        break;
238|      case 'RET':
239|        if (csp === 0) return trap(TRAP.RET_EMPTY);
240|        pc = C[--csp];
241|        break;
242|      case 'LOAD': {
243|        const addr = D[sp - 1];
244|        if (addr < 0 || addr >= MEMORY_WORDS) return trap(TRAP.MEMORY);
245|        D[sp - 1] = M[addr];
246|        break;
247|      }
248|      case 'STORE': {
249|        const addr = D[sp - 1];
250|        const v = D[sp - 2];
251|        if (addr < 0 || addr >= MEMORY_WORDS) return trap(TRAP.MEMORY);
252|        sp -= 2;
253|        M[addr] = v;
254|        break;
255|      }
256|      case 'PRINT': {
257|        const bytes = enc.encode(String(D[sp - 1]));
258|        if (olen + bytes.length > OUTPUT_MAX) return trap(TRAP.OUTPUT);
259|        sp--;
260|        out.set(bytes, olen);
261|        olen += bytes.length;
262|        break;
263|      }
264|      case 'PUTC':
265|        if (olen + 1 > OUTPUT_MAX) return trap(TRAP.OUTPUT);
266|        out[olen++] = D[--sp] & 255;
267|        break;
268|      case 'IN':
269|        D[sp++] = inPos < input.length ? input[inPos++] : -1;
270|        break;
271|      case 'EXIT':
272|        return done(D[--sp] & 255, null);
273|    }
274|  }
