{"content": "1|// The scorer (program/v1, node22). It runs after the entry, in a container of its own: the entry's outputs read-only
2|// at /output, the instance's reference read-only at /reference (generator/draw.ts writes it: manifest.json and a copy of
3|// every instance file under <id>/), and /scores writable. It never runs the entry's code: it reads the entry's answer
4|// files and hands them to the checker (checker/check.mjs), a pure module that reads no file.
5|//
6|// Each instance's answer is its OUTPUTS files at /output/<id>/<name>, each a regular file (never through a link) of at
7|// most its max_bytes, a text one UTF-8. An instance missing any of them, or one the checker calls invalid, is
8|// unanswered: 0 points. Otherwise its points are the checker's points(files, key, outputs), 0 to 1000.
9|//
10|// It writes
11|//   /scores/scores.json  score (1000 x the mean points, rounded half up: 0 to 1000000), passed (1 when every instance
12|//                        is answered in its stated format: the gate), answered, instances, and each instance's points x
13|//                        1000, rounded half up (i001, ...: hidden columns)
14|//   /scores/checks.json  one row per instance: its points of 1000, passing when answered, the checker's detail
15|//
16|// A reference that does not read, or a checker that throws or answers outside {points 0 to 1000, valid, detail} (points
17|// for an answer it calls invalid included), is the scorer's fault: it exits 1, never the entry's. Outside a container
18|// MAKEFUN_OUTPUT_DIR, MAKEFUN_REFERENCE_DIR and MAKEFUN_SCORES_DIR stand in for the mounts.
19|
20|import { createHash } from 'node:crypto';
21|import { lstatSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
22|import { join } from 'node:path';
23|
24|/** The subject's checker, imported by its URL (a .mjs or .js module carries no types) and typed by its contract. */
25|const { points } = (await import(new URL("./checker/check.mjs", import.meta.url).href)) as {
26|  points: (files: Record<string, string | Uint8Array>, key: unknown, outputs: Record<string, string | Uint8Array>) => unknown;
27|};
28|
29|const OUTPUT_DIR = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
30|const REFERENCE_DIR = process.env.MAKEFUN_REFERENCE_DIR ?? '/reference';
31|const SCORES_DIR = process.env.MAKEFUN_SCORES_DIR ?? '/scores';
32|
33|const MANIFEST_FORMAT = "makefun/solver-home/manifest/v1";
34|/** How many instances a set holds. */
35|const INSTANCES = 40;
36|/** Each instance's answer files. */
37|const OUTPUTS: readonly { name: string; kind: 'text' | 'bytes'; max_bytes: number }[] = [
38|  { name: "stdout.bin", kind: "bytes", max_bytes: 65536 },
39|  { name: "exit.txt", kind: "text", max_bytes: 16 },
40|];
41|const POINTS_MAX = 1000;
42|/** The longest detail a check row carries. */
43|const DETAIL_MAX = 2000;
44|
45|type Kind = 'text' | 'bytes';
46|interface Instance {
47|  id: string;
48|  files: { name: string; kind: Kind; sha256: string }[];
49|  key: unknown;
50|}
51|
52|const utf8 = new TextDecoder('utf-8', { fatal: true });
53|const sha256 = (b: Uint8Array): string => createHash('sha256').update(b).digest('hex');
54|const idOf = (k: number): string => 'i' + String(k + 1).padStart(3, '0');
55|
56|function readManifest(): Instance[] {
57|  const file = join(REFERENCE_DIR, 'manifest.json');
58|  if (!lstatSync(file).isFile()) throw new Error('the reference manifest.json is not a regular file');
59|  const doc = JSON.parse(readFileSync(file, 'utf8')) as { format?: unknown; instances?: unknown };
60|  if (doc.format !== MANIFEST_FORMAT || !Array.isArray(doc.instances)) throw new Error('the reference manifest.json is not ' + MANIFEST_FORMAT);
61|  if (doc.instances.length !== INSTANCES) throw new Error('the reference manifest.json lists ' + doc.instances.length + ' instances, not ' + INSTANCES);
62|  const list = doc.instances as Instance[];
63|  list.forEach((inst, k) => {
64|    if (inst.id !== idOf(k) || !Array.isArray(inst.files) || inst.files.length === 0) throw new Error('the reference manifest.json holds a malformed instance at ' + k);
65|  });
66|  return list;
67|}
68|
69|/** The instance's files as generate wrote them, each checked against the manifest's sha256. */
70|function filesOf(inst: Instance): Record<string, string | Uint8Array> {
71|  const out: Record<string, string | Uint8Array> = {};
72|  for (const f of inst.files) {
73|    const path = join(REFERENCE_DIR, inst.id, f.name);
74|    if (!lstatSync(path).isFile()) throw new Error('reference/' + inst.id + '/' + f.name + ' is not a regular file');
75|    const bytes = new Uint8Array(readFileSync(path));
76|    if (sha256(bytes) !== f.sha256) throw new Error('reference/' + inst.id + '/' + f.name + ' does not match the manifest');
77|    out[f.name] = f.kind === 'text' ? utf8.decode(bytes) : bytes;
78|  }
79|  return out;
80|}
81|
82|/** The entry's answer files of instance id, or why it has none to score. */
83|function outputsOf(id: string): { outputs: Record<string, string | Uint8Array> } | { why: string } {
84|  const dir = join(OUTPUT_DIR, id);
85|  let st;
86|  try {
87|    st = lstatSync(dir);
88|  } catch {
89|    return { why: 'no /output/' + id + '/' };
90|  }
91|  if (!st.isDirectory()) return { why: '/output/' + id + ' is not a directory' };
92|  const outputs: Record<string, string | Uint8Array> = {};
93|  for (const o of OUTPUTS) {
94|    const path = join(dir, o.name);
95|    const shown = '/output/' + id + '/' + o.name;
96|    let f;
97|    try {
98|      f = lstatSync(path);
99|    } catch {
100|      return { why: 'no ' + shown };
101|    }
102|    if (!f.isFile()) return { why: shown + ' is not a regular file' };
103|    if (f.size > o.max_bytes) return { why: shown + ' is ' + f.size + ' bytes, over its ' + o.max_bytes };
104|    const bytes = new Uint8Array(readFileSync(path));
105|    if (o.kind === 'bytes') outputs[o.name] = bytes;
106|    else {
107|      try {
108|        outputs[o.name] = utf8.decode(bytes);
109|      } catch {
110|        return { why: shown + ' is not UTF-8 text' };
111|      }
112|    }
113|  }
114|  return { outputs };
115|}
116|
117|/** The checker's verdict on one answer, held to its shape (the header). */
118|async function verdictOf(inst: Instance, outputs: Record<string, string | Uint8Array>): Promise<{ points: number; valid: boolean; detail: string | null }> {
119|  const r = (await points(filesOf(inst), inst.key, outputs)) as { points?: unknown; valid?: unknown; detail?: unknown } | null;
120|  const where = 'the checker\'s points() on ' + inst.id;
121|  if (r === null || typeof r !== 'object') throw new Error(where + ' answered no {points, valid, detail}');
122|  if (typeof r.points !== 'number' || !Number.isFinite(r.points) || r.points < 0 || r.points > POINTS_MAX) throw new Error(where + ' gave points ' + String(r.points) + ', not 0 to ' + POINTS_MAX);
123|  if (typeof r.valid !== 'boolean') throw new Error(where + ' answered no valid boolean');
124|  if (!r.valid && r.points !== 0) throw new Error(where + ' gave ' + r.points + ' points to an answer it calls invalid');
125|  if (r.detail !== undefined && r.detail !== null && typeof r.detail !== 'string') throw new Error(where + ' answered a detail that is not a string');
126|  return { points: r.points, valid: r.valid, detail: typeof r.detail === 'string' && r.detail !== '' ? r.detail : null };
127|}
128|
129|const rows: { id: string; points: number; valid: boolean; detail: string | null }[] = [];
130|for (const inst of readManifest()) {
131|  const read = outputsOf(inst.id);
132|  if ('why' in read) rows.push({ id: inst.id, points: 0, valid: false, detail: read.why });
133|  else rows.push({ id: inst.id, ...(await verdictOf(inst, read.outputs)) });
134|}
135|
136|const half = (x: number): number => Math.floor(x + 0.5);
137|const total = rows.reduce((a, r) => a + r.points, 0);
138|const answered = rows.filter((r) => r.valid).length;
139|const scores: Record<string, number> = { score: half((total * POINTS_MAX) / rows.length), passed: answered === rows.length ? 1 : 0, answered, instances: rows.length };
140|for (const r of rows) scores[r.id] = half(r.points * POINTS_MAX);
141|const checks = rows.map((r) => ({
142|  key: r.id,
143|  group: 'Instances',
144|  title: 'Instance ' + r.id,
145|  points: POINTS_MAX,
146|  earned: Math.round(r.points * 1000) / 1000,
147|  pass: r.valid,
148|  ...(r.detail === null ? {} : { detail: r.detail.slice(0, DETAIL_MAX) }),
149|}));
150|
151|mkdirSync(SCORES_DIR, { recursive: true });
152|writeFileSync(join(SCORES_DIR, 'scores.json'), JSON.stringify(scores) + '\n');
153|writeFileSync(join(SCORES_DIR, 'checks.json'), JSON.stringify(checks) + '\n');", "total_lines": 153, "file_size": 8198, "truncated": false, "is_binary": false, "is_image": false}

