6|import { readdirSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
7|import { join } from 'node:path';
8|
9|const STACK_MAX = 256;
10|const CALLS_MAX = 64;
11|const MEMORY_WORDS = 256;
12|const STEP_LIMIT = 1_000_000;
13|const OUTPUT_MAX = 65_536;
14|
15|const TRAP = {
16|  UNDERFLOW: 2, OVERFLOW: 3, DIV_ZERO: 4, BAD_OPCODE: 5, MEMORY: 6,
17|  CALL_DEPTH: 7, RET_EMPTY: 8, PC: 9, STEPS: 10, OUTPUT: 11,
18|} as const;
19|
20|// byte -> [name, immediate bytes, pops, pushes]
21|const OPS = new Map<number, [string, number, number, number]>([
22|  [0x00, ['HALT', 0, 0, 0]],
23|  [0x01, ['PUSH8', 1, 0, 1]],
24|  [0x02, ['PUSH32', 4, 0, 1]],
25|  [0x03, ['POP', 0, 1, 0]],
26|  [0x04, ['DUP', 0, 1, 2]],
27|  [0x05, ['SWAP', 0, 2, 2]],
28|  [0x06, ['OVER', 0, 2, 3]],
29|  [0x07, ['ROT', 0, 3, 3]],
30|  [0x10, ['ADD', 0, 2, 1]],
31|  [0x11, ['SUB', 0, 2, 1]],
32|  [0x12, ['MUL', 0, 2, 1]],
33|  [0x13, ['DIV', 0, 2, 1]],
34|  [0x14, ['MOD', 0, 2, 1]],
35|  [0x15, ['DIVU', 0, 2, 1]],
36|  [0x16, ['MODU', 0, 2, 1]],
37|  [0x17, ['NEG', 0, 1, 1]],
38|  [0x18, ['AND', 0, 2, 1]],
39|  [0x19, ['OR', 0, 2, 1]],
40|  [0x1a, ['XOR', 0, 2, 1]],
41|  [0x1b, ['NOT', 0, 1, 1]],
42|  [0x1c, ['SHL', 0, 2, 1]],
43|  [0x1d, ['SHR', 0, 2, 1]],
44|  [0x1e, ['SHRU', 0, 2, 1]],
45|  [0x20, ['EQ', 0, 2, 1]],
46|  [0x21, ['LT', 0, 2, 1]],
47|  [0x22, ['LTU', 0, 2, 1]],
